"use client";

import React, { Suspense, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useSession } from "next-auth/react";
import { FiSend } from "react-icons/fi";
import { ConversationFilters } from "@/components/dashboard";
import ConciergeWorkspacePage from "../_components/ConciergeWorkspacePage";
import { ConversationDetailResponse, ConversationItem } from "./messagesClient";
import { useConciergeMessages } from "./useConciergeMessages";
import styles from "./MessagesPage.module.scss";

interface ConversationListSidebarProps {
  conversations: ConversationItem[];
  activeConversationId: string;
  listLoading: boolean;
  searchTerm: string;
  statusFilter: string;
  onSearchChange: (value: string) => void;
  onStatusChange: (value: string) => void;
  onSelect: (conversationId: string) => void;
}

interface ConversationThreadProps {
  activeConversationId: string;
  detailLoading: boolean;
  activeConversation: ConversationDetailResponse | null;
  participantNameById: Map<string, string>;
  draftMessage: string;
  sending: boolean;
  canSend: boolean;
  onDraftChange: (value: string) => void;
  onSend: () => void;
}

const formatDateTime = (value?: string | null): string => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";

  return new Intl.DateTimeFormat("fr-FR", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
};

function getConversationTitle(subject?: string | null) {
  return subject || "Conversation";
}

function getConversationContextLabel(source?: string | null, status?: string | null) {
  switch ((source ?? "").trim().toLowerCase()) {
    case "mission":
      return "Mission";
    case "quote":
      return "Devis";
    case "search":
      return "Recherche proprietaire";
    case "service_request":
    case "request":
      return "Demande";
    case "manual":
    case "direct":
      return "Conversation directe";
    default:
      return status || source || "Conversation";
  }
}

function ConversationListSidebar({
  conversations,
  activeConversationId,
  listLoading,
  searchTerm,
  statusFilter,
  onSearchChange,
  onStatusChange,
  onSelect,
}: ConversationListSidebarProps) {
  return (
    <aside className={styles.sidebar}>
      <div className={styles.sidebarHeader}>
        <h2>Conversations prioritaires</h2>
        {listLoading && <span>MAJ...</span>}
      </div>

      <ConversationFilters
        searchValue={searchTerm}
        onSearchChange={onSearchChange}
        searchPlaceholder="Rechercher un propriétaire ou un sujet"
        searchLabel="Rechercher une conversation propriétaire"
        statusValue={statusFilter}
        onStatusChange={onStatusChange}
        statusLabel="Filtrer les conversations propriétaire par statut"
        statusOptions={[
          { value: "all", label: "Tous statuts" },
          { value: "open", label: "Ouverts" },
          { value: "closed", label: "Fermés" },
        ]}
        containerClassName={styles.toolbar}
        searchClassName={styles.searchField}
        selectClassName={styles.filterSelect}
      />

      {conversations.length === 0 ? (
        <p className={styles.emptyState}>Aucune conversation pour le moment.</p>
      ) : (
        <div className={styles.conversationList}>
          {conversations.map((conversation) => (
            <button
              key={conversation.id}
              type="button"
              onClick={() => onSelect(conversation.id)}
              className={`${styles.conversationItem} ${
                activeConversationId === conversation.id ? styles.conversationItemActive : ""
              }`}
            >
              <div className={styles.conversationHead}>
                <strong>{conversation.counterpart_name}</strong>
                <span>{formatDateTime(conversation.last_message_at)}</span>
              </div>
              <p>{getConversationTitle(conversation.subject)}</p>
              <small>{conversation.last_message_preview || "Aucun message"}</small>
            </button>
          ))}
        </div>
      )}
    </aside>
  );
}

function ConversationThread({
  activeConversationId,
  detailLoading,
  activeConversation,
  participantNameById,
  draftMessage,
  sending,
  canSend,
  onDraftChange,
  onSend,
}: ConversationThreadProps) {
  if (!activeConversationId) {
    return (
      <section className={styles.thread}>
        <p className={styles.emptyState}>Sélectionnez une conversation.</p>
      </section>
    );
  }

  if (detailLoading) {
    return (
      <section className={styles.thread}>
        <p className={styles.emptyState}>Chargement de la conversation...</p>
      </section>
    );
  }

  if (!activeConversation) {
    return (
      <section className={styles.thread}>
        <p className={styles.emptyState}>Conversation indisponible.</p>
      </section>
    );
  }

  return (
    <section className={styles.thread}>
      <div className={styles.threadHeader}>
        <h2>{getConversationTitle(activeConversation.conversation.subject)}</h2>
        <span>
          {getConversationContextLabel(
            activeConversation.conversation.source,
            activeConversation.conversation.status,
          )}
        </span>
      </div>

      <div className={styles.messageList}>
        {activeConversation.messages.length === 0 && (
          <p className={styles.emptyState}>Aucun message.</p>
        )}
        {activeConversation.messages.map((message) => {
          const isMe = message.sender_profile_id === activeConversation.current_user_id;
          return (
            <article
              key={message.id}
              className={`${styles.message} ${isMe ? styles.messageMine : styles.messageOther}`}
            >
              <div className={styles.messageMeta}>
                <strong>{participantNameById.get(message.sender_profile_id) || "Utilisateur"}</strong>
                <span>{formatDateTime(message.created_at)}</span>
              </div>
              <p>{message.body}</p>
            </article>
          );
        })}
      </div>

      <div className={styles.composer}>
        <textarea
          value={draftMessage}
          onChange={(event) => onDraftChange(event.target.value)}
          placeholder="Écrire votre message..."
          aria-label="Écrire votre message"
        />
        <button type="button" onClick={onSend} disabled={sending || !canSend}>
          <FiSend size={14} />
          {sending ? "Envoi..." : "Envoyer"}
        </button>
      </div>
    </section>
  );
}

function ConciergeMessagesContent() {
  const { status } = useSession();
  const router = useRouter();
  const searchParams = useSearchParams();
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");

  const queryConversationId = searchParams.get("conversation") ?? "";

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/login");
    }
  }, [status, router]);

  const {
    loading,
    listLoading,
    detailLoading,
    errorMsg,
    successMsg,
    conversations,
    activeConversationId,
    activeConversation,
    draftMessage,
    sending,
    canSend,
    participantNameById,
    setActiveConversationId,
    setDraftMessage,
    sendMessage,
    reload,
  } = useConciergeMessages({
    enabled: status === "authenticated",
    queryConversationId,
  });

  const filteredConversations = useMemo(() => {
    const normalizedSearch = searchTerm.trim().toLowerCase();
    return conversations.filter((conversation) => {
      const matchesStatus = statusFilter === "all" || conversation.status === statusFilter;
      if (!matchesStatus) return false;
      if (!normalizedSearch) return true;

      const haystack = [
        conversation.counterpart_name,
        conversation.subject,
        conversation.last_message_preview,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      return haystack.includes(normalizedSearch);
    });
  }, [conversations, searchTerm, statusFilter]);

  const openCount = useMemo(
    () => conversations.filter((conversation) => conversation.status === "open").length,
    [conversations],
  );

  if (loading) {
    return <div className={styles.page} role="status" aria-busy="true">Chargement des messages...</div>;
  }

  return (
    <ConciergeWorkspacePage
      eyebrow="Relation propriétaires"
      title="Messages propriétaires"
      description="Centralisez vos échanges propriétaires, vos relances et vos fils actifs depuis une seule vue de pilotage."
      chips={[
        `${conversations.length} conversation(s)`,
        `${openCount} ouverte(s)`,
        activeConversation
          ? getConversationTitle(activeConversation.conversation.subject)
          : "Aucune conversation active",
      ]}
      metrics={[
        {
          label: "Conversations",
          value: `${conversations.length}`,
          hint: `${filteredConversations.length} visible(s) avec vos filtres`,
        },
        {
          label: "Ouvertes",
          value: `${openCount}`,
          hint: "Fils qui demandent encore un suivi",
        },
        {
          label: "Messages",
          value: `${activeConversation?.messages.length ?? 0}`,
          hint: "Dans la conversation active",
        },
      ]}
      actions={[
        { label: "Voir le pilotage terrain", href: "/dashboard/concierge/planning" },
        { label: "Voir les objectifs", href: "/dashboard/concierge/objectifs" },
      ]}
      cards={[
        {
          title: "Suivi relationnel",
          text:
            openCount > 0
              ? `${openCount} conversation(s) restent ouvertes avec vos propriétaires. Priorisez celles qui font avancer signature, exécution ou satisfaction.`
              : "Aucune conversation ouverte pour le moment.",
        },
        {
          title: "Conversation active",
          text: activeConversation
            ? `${getConversationTitle(activeConversation.conversation.subject)} - ${activeConversation.messages.length} message(s)`
            : "Sélectionnez un fil pour voir le détail des échanges.",
        },
      ]}
    >
      {errorMsg ? (
        <div className={styles.errorBox} role="alert">
          <span>{errorMsg}</span>
          <button type="button" onClick={() => void reload()}>
            Réessayer
          </button>
        </div>
      ) : null}
      {successMsg ? <div className={styles.successBox} role="status">{successMsg}</div> : null}

      <div className={styles.layout} aria-busy={listLoading || detailLoading || sending}>
        <ConversationListSidebar
          conversations={filteredConversations}
          activeConversationId={activeConversationId}
          listLoading={listLoading}
          searchTerm={searchTerm}
          statusFilter={statusFilter}
          onSearchChange={setSearchTerm}
          onStatusChange={setStatusFilter}
          onSelect={setActiveConversationId}
        />
        <ConversationThread
          activeConversationId={activeConversationId}
          detailLoading={detailLoading}
          activeConversation={activeConversation}
          participantNameById={participantNameById}
          draftMessage={draftMessage}
          sending={sending}
          canSend={canSend}
          onDraftChange={setDraftMessage}
          onSend={sendMessage}
        />
      </div>
    </ConciergeWorkspacePage>
  );
}

export default function ConciergeMessagesPage() {
  return (
    <Suspense fallback={<div className={styles.page}>Chargement des messages...</div>}>
      <ConciergeMessagesContent />
    </Suspense>
  );
}

